 99		A strategy $\mathcal S = (\ket{\psi}, A, B)$ is \emph{symmetric} if $\ket{\psi}$ is a (pure) state in $\mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, that is invariant under permutation of the two factors, and the measurement operators of both players are identical.
100	\end{definition}
101	
102	We often specify symmetric games $\mathfrak G$ and symmetric strategies $\mathcal S$ using a compact notation: we write $\mathfrak G = (\mathcal X, \mathcal A, \mu, D)$ and $\mathcal S = (\ket{\psi}, M)$, where $M$ denotes the set of measurement operators shared by both players.
103	
104	\begin{lemma}[Symmetrization of strategies for symmetric games]\label{lem:symmetric-strat}
105		\uses{def:symmetric-game, def:tensor-product-value, def:projective-strategy-general}
106		Let $\mathfrak G = (\mathcal X, \mathcal A, \mu, D)$ be a symmetric game such that $\operatorname{val}^*(\mathfrak G) = 1-\eps$ for some $\eps \ge 0$. Then there exists a symmetric and projective strategy $\mathcal S = (\ket{\psi}, M)$ such that $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge 1-\eps$.
107	\end{lemma}
108	\begin{proof}
109		\uses{thm:naimark}
110		By definition, for any $\eps' > \eps$ there exists a strategy $\mathcal S' = (\ket{\psi'}, A, B)$ with $\operatorname{val}^*(\mathfrak G, \mathcal S') \ge 1-\eps'$. Using Naimark dilation (Theorem~\ref{thm:naimark}, in the completed form recorded in Remark~\ref{rem:naimark-for-games}) we may assume without loss of generality that $\ket{\psi'} \in \C^d_{A'} \ot \C^d_{B'}$ for some integer $d$ and that every $A^x$ and $B^x$ is a projective measurement. Let
111		\[
112			\ket{\psi} = \frac{1}{\sqrt 2}\, \bigl( \ket{0}_{A}\ket{1}_{B}\ket{\psi'}_{A'B'} + \ket{1}_{A}\ket{0}_{B}\ket{\psi'_\tau}_{A'B'} \bigr) \in \bigl(\C^2_{A} \ot \C^d_{A'}\bigr) \ot \bigl(\C^2_{B} \ot \C^d_{B'}\bigr)\,,
113		\]
114		where $\ket{\psi'_\tau}$ is obtained from $\ket{\psi'}$ by permuting the two players' registers; then $\ket{\psi}$ is invariant under permutation of the register pairs $AA'$ and $BB'$. For each question $x \in \mathcal X$ define the projective measurement $M^x = \{M^x_a\}_{a \in \mathcal A}$ on $\C^2 \ot \C^d$ by
115		\[
116			M^x_a = \ket{0}\bra{0} \ot A^x_a + \ket{1}\bra{1} \ot B^x_a\,,
117		\]
118		and let each player measure $M$ on their pair of registers. Because the decision predicate $D$ of the symmetric game treats the two players symmetrically, the resulting symmetric projective strategy $\mathcal S = (\ket{\psi}, M)$ satisfies $\operatorname{val}^*(\mathfrak G, \mathcal S) = \operatorname{val}^*(\mathfrak G, \mathcal S')$. The passage from a value of at least $1-\eps'$ for every $\eps' > \eps$ to a value of at least $1-\eps$ is discussed in Remark~\ref{rem:symmetric-strat-limit}.
119	\end{proof}
120	
121	\begin{remark}[Limit step in the symmetrization lemma]\label{rem:symmetric-strat-limit}
122		The construction in the proof of Lemma~\ref{lem:symmetric-strat} produces, for every $\eps' > \eps$, a symmetric projective strategy of value at least $1-\eps'$; the source asserts the conclusion for $\eps$ itself without giving the limiting argument. Since the dilated dimension $d$ may grow as $\eps' \downarrow \eps$, this final step is not immediate; it requires an additional compactness or limit argument, or else the conclusion should be read as: for every $\eps' > \eps$ there exists a symmetric projective strategy of value at least $1-\eps'$.
123	\end{remark}
