333	\begin{lemma}[Sandwiched simultaneous measurement; modified from Fact 4.34 in \cite{Natarajan2018NEEXP}]\label{lem:ld-sandwich}
334		\uses{def:consistency, def:bracket, def:povm-conventions}
335		Let $k \ge 0$ be an integer and let $\eps > 0$. Let $\mathcal X$ be a finite set and $\mu$ a distribution over $\mathcal X$. For each $1 \le i \le k$ let $\mathcal G_i$ be a finite set of functions $g_i \colon \mathcal Y \to \mathcal R_i$, and for each $x \in \mathcal X$ let $\{G^{i,\,x}_g\}_{g \in \mathcal G_i}$ be a projective measurement. Suppose that for all $i \in \{1,\dots,k\}$ the set $\mathcal G_i$ satisfies the following property: for any two $g_i \ne g_i' \in \mathcal G_i$, the probability that $g_i(y) = g_i'(y)$ over a uniformly random $y \in \mathcal Y$ is at most $\eps$.
336	
337		Let $\bigl\{ A^x_{g_1,\,g_2,\,\dots,\,g_k} \bigr\}$ be a projective measurement with outcomes $(g_1,\dots,g_k) \in \mathcal G_1 \times \cdots \times \mathcal G_k$. Here $\operatorname{eval}_y$ denotes the evaluation map $g \mapsto g(y)$, so that $A^x_{[\operatorname{eval}_y(\cdot)_i = a_i]}$ post-processes the outcome tuple by evaluating its $i$-th component at $y$ (Definition~\ref{def:bracket}). For each $1 \le i \le k$, suppose that on average over $x \sim \mu$ and $y \in \mathcal Y$ sampled uniformly at random,
338		\begin{equation}\label{eq:ld-sandwich-1}
339			A^x_{[\operatorname{eval}_y(\cdot)_i = a_i]} \ot \Id_B \simeq_{\delta} \Id_A \ot G^{i,\,x}_{[\operatorname{eval}_y(\cdot) = a_i]}\,.
340		\end{equation}
341		Define the POVM family $\{C^x_{g_1,\,g_2,\,\dots,\,g_k}\}$, for $x \in \mathcal X$, by
342		\[
343			C^x_{g_1,\,g_2,\,\dots,\,g_k} = G^{k,\,x}_{g_1} \cdots G^{2,\,x}_{g_{k-1}}\; G^{1,\,x}_{g_k}\; G^{2,\,x}_{g_{k-1}} \cdots G^{k,\,x}_{g_1}\,.
344		\]
345		Then on average over $x \sim \mu$ and $y \in \mathcal Y$ sampled uniformly at random,
346		\begin{equation}\label{eq:ld-sandwich-2}
347			A^x_{[\operatorname{eval}_y(\cdot) = (a_1,\,a_2,\,\dots,\,a_k)]} \ot \Id_B \simeq_{k(\delta+\eps)^{1/2}} \Id_A \ot C^x_{[\operatorname{eval}_y(\cdot) = (a_1,\,a_2,\,\dots,\,a_k)]}\,.
348		\end{equation}
349	\end{lemma}
350	\begin{proof}
351		The source proof is a citation: the argument is identical to the proof of Fact 4.34 in \cite{Natarajan2018NEEXP}, with the only modification being the insertion of the dependence on the question $x$ for all measurements considered. In outline, the consistency hypotheses \eqref{eq:ld-sandwich-1} allow one to insert the projective factors $G^{i,\,x}$ next to $A^x$ one index at a time, and the $\eps$-bound on the pairwise agreement of distinct functions in $\mathcal G_i$ controls the events on which two different outcomes collide at the sampled point $y$. Each of the $k$ insertions costs $(\delta+\eps)^{1/2}$ by the Cauchy--Schwarz inequality, producing the sandwich $C^x$ with total error $k(\delta+\eps)^{1/2}$.
352	\end{proof}
353	
354	\begin{remark}[Index pairing in the sandwich]\label{rem:ld-sandwich-indexing}
355		As printed in the source, the sandwich in Lemma~\ref{lem:ld-sandwich} pairs the $i$-th measurement with the outcome $g_{k+1-i}$: the outermost factor $G^{k,\,x}$ carries the outcome $g_1$ and the innermost factor $G^{1,\,x}$ carries $g_k$. In Fact 4.34 of \cite{Natarajan2018NEEXP}, from which the lemma is imported, the natural pairing $G^{k,\,x}_{g_k} \cdots G^{1,\,x}_{g_1} \cdots G^{k,\,x}_{g_k}$ is used. The transposed indices appear to be a typographical slip in the source; the statement above records the source text as written, and any use of the lemma should confirm the intended pairing against \cite{Natarajan2018NEEXP}.
356	\end{remark}
