  8	\section{Measurements and observables}
  9	
 10	\begin{definition}[POVMs, sub-measurements, and observables]\label{def:povm-conventions}
 11		\uses{def:submeasurement}
 12		Quantum measurements are modeled as positive operator-valued measures (POVMs). A \emph{POVM} on a finite-dimensional Hilbert space $\mathcal H$ is a family of positive semidefinite operators $\{M_a\}_{a \in S}$ indexed by outcomes $a \in S$ such that $\sum_a M_a = \Id$; if the latter condition is relaxed to $\sum_a M_a \le \Id$, then $\{M_a\}$ is a \emph{sub-measurement}. (POVMs and sub-measurements are thus exactly the measurements and submeasurements of Definition~\ref{def:submeasurement}.) The probability that the measurement returns outcome $a$ on a state $\ket{\psi}$ is
 13		\[
 14			\Prb(a) = \bra{\psi} M_a \ket{\psi}\,.
 15		\]
 16		A POVM $M = \{M_a\}$ is \emph{projective} if each operator $M_a$ is a projector ($M_a^2 = M_a$); this automatically implies that $M_a M_b = M_b M_a = 0$ for distinct outcomes $a \ne b$. An \emph{observable} is a unitary matrix. A \emph{binary observable} is an observable $O$ such that $O^2 = \Id$, i.e.\ $O$ has eigenvalues in $\{-1,1\}$.
 17	
 18		Subscripts of a measurement index the outcome, and superscripts index different measurements. When the outcome of a measurement $\{M^x_{a,\,b}\}$ consists of two parts $a$ and $b$, we write $\{M^x_a\}$ and $\{M^x_b\}$ for its \emph{marginals}
 19		\[
 20			M^x_a = \sum_b M^x_{a,\,b}\,, \qquad M^x_b = \sum_a M^x_{a,\,b}\,;
 21		\]
 22		for every $x$ both marginals are again POVMs.
 23	\end{definition}
 24	
 25	\begin{definition}[Bracket notation for post-processed measurements]\label{def:bracket}
 26		\uses{def:povm-conventions, def:post-processing}
 27		Let $\{M^x_a\}_{a \in \mathcal A}$ be a family of POVMs indexed by $x \in \mathcal X$, and let $f \colon \mathcal A \to \mathcal B$ be an arbitrary function. We write $\bigl\{ M^x_{[f(\cdot)=b]} \bigr\}$ for the POVM derived from $\{M^x_a\}$ by applying the function $f$ to the outcome before returning it:
 28		\[
 29			M^x_{[f(\cdot)=b]} = \sum_{a\,:\,f(a)=b} M^x_a\,,
 30		\]
 31		and $M^x_{[f(\cdot)=b]} = 0$ when $b$ is not in the image of $f$. When the outcome $a$ has a natural interpretation as a tuple $(a_1,\dots,a_k)$, we also write, for $i \in \{1,\dots,k\}$,
 32		\[
 33			M^x_{[a_i=b]} = \sum_{(a_1,\dots,a_k)\,:\,a_i=b} M^x_{(a_1,\dots,a_k)}\,.
 34		\]
 35		For each fixed $x$ this is the post-processing operation of Definition~\ref{def:post-processing}.
 36	\end{definition}
 37	
 38	\begin{remark}[Naimark dilation for strategies]\label{rem:naimark-for-games}
 39		The symmetrization argument of Lemma~\ref{lem:symmetric-strat} below invokes Naimark dilation in the form of Theorem~\ref{thm:naimark} (stated and proved in Chapter~\ref{chap:projective}): a bipartite state together with two sub-measurement families can be replaced, without changing any of the correlations $\bra{\psi} A^x_a \ot B^y_b \ket{\psi}$, by a product-extended state together with projective sub-measurements on the enlarged spaces. When the input families are complete measurements, the dilated projective sub-measurements can be completed by assigning the residual projector of each family to one fixed outcome; the resulting projective measurements reproduce the same correlations on the extended state, since the correlation-preservation identity forces the extended state to lie in the range of the total projector of each dilated family. This completed form, with genuinely projective measurements, is the one used in Lemma~\ref{lem:symmetric-strat}; for the proof the source refers to Theorem 5.1 of \cite{Ji2020LowIndividualDegree}, which is stated for complete measurements. The source follows its statement of the dilation theorem with a sentence announcing an ``orthogonalization lemma'' from the literature that is never actually stated there; nothing in this chapter depends on it.
 40	\end{remark}
