453	\begin{lemma}[Concatenation of conditionally linear functions]\label{lem:cl-concat}
454		\uses{def:cl-func}
455		Let $\ell, k \ge 0$ be integers and let $U = \F^n$, $V = \F^m$ be linear spaces. Suppose $L$ is a $k$-level CL function on $U$ and, for each $u \in L(U)$, $R_u$ is an $\ell$-level CL function on $V$. Then the \emph{concatenation} $T$ of $L$ and $\{R_u\}_u$, defined by
456		\[
457			T(x) = L(x^U) + R_{L(x^U)}(x^V)\,,
458		\]
459		is a $(k+\ell)$-level conditionally linear function on $U \oplus V$.
460	\end{lemma}
461	\begin{proof}
462		By induction on $k$. The case $k = 0$ follows directly from Definition~\ref{def:cl-func}, since then $L = 0$ and $T$ acts by the single $\ell$-level function $R_0$ on the register subspace $V$. For the inductive step, write $L(x^U) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{U_{>1}})$ with complementary register subspaces $U_1$ and $U_{>1}$ of $U$. For each value $x^{L_1}$, the function $T_{>1,\,x^{L_1}}$ on $U_{>1} \oplus V$ sending $x^{U_{>1} \oplus V}$ to $L_{>1,\,x^{L_1}}(x^{U_{>1}}) + R_{x^{L_1} + x^{L_{>1}}}(x^V)$ is the concatenation of the $(k-1)$-level function $L_{>1,\,x^{L_1}}$ with a family drawn from $\{R_u\}$, hence is $(k+\ell-1)$-level by the induction hypothesis. The claim then follows from Definition~\ref{def:cl-func} applied with first subspace $U_1$ and first linear map $L_1$.
463	\end{proof}
464	
465	\begin{lemma}[Direct sums of conditionally linear functions]\label{lem:cl-func-prod}
466		\uses{def:cl-func, def:register-subspace}
467		Let $V^{(1)}, V^{(2)}, \dots, V^{(m)}$ be register subspaces of $V$ such that $V = \bigoplus_{j=1}^m V^{(j)}$. Suppose that, for each $j \in \{1, 2, \dots, m\}$, $L^{(j)}$ is an $\ell_j$-level conditionally linear function on $V^{(j)}$. Then the direct sum $L = \bigoplus_{j=1}^m L^{(j)}$, defined by
468		\[
469			L(x) = \sum_{j=1}^m L^{(j)}(x^{(j)})
470		\]
471		for all $x = \sum_{j=1}^m x^{(j)} \in \bigoplus_{j=1}^m V^{(j)}$, is an $\ell$-level CL function on $V$ for $\ell = \max_j \{\ell_j\}$.
472	\end{lemma}
473	\begin{proof}
474		Since an $\ell$-level CL function is also $k$-level conditionally linear for all $k \ge \ell$, it suffices to prove the claim when $\ell_j = \ell$ for all $j$. Proceed by induction on $\ell$. For $\ell = 1$ the functions $L^{(j)}$ are linear and the direct sum of linear maps is linear. For the inductive step, decompose each $L^{(j)}$ into its first-level linear part $L^{(j)}_1$ on $V^{(j)}_1$ and its family of $(\ell-1)$-level remainders $L^{(j)}_{>1,\,v_j}$ on $V^{(j)}_{>1}$. The direct sums of the first-level parts define a linear map on $V_1 = \bigoplus_j V^{(j)}_1$, and, for each prefix value $v = \sum_j v_j$, the direct sums of the remainders are $(\ell-1)$-level conditionally linear on $V_{>1} = \bigoplus_j V^{(j)}_{>1}$ by the induction hypothesis. This exhibits $L$ in the form required by Definition~\ref{def:cl-func}.
475	\end{proof}
476	
477	\begin{lemma}[Direct sums give product distributions]\label{lem:cl-dist-prod}
478		\uses{def:cl-dist, lem:cl-func-prod}
479		For each $i \in \{1, \dots, m\}$ let $L^{(i)}, R^{(i)} \colon V^{(i)} \to V^{(i)}$ be $\ell_i$-level conditionally linear functions, and let $L, R \colon V \to V$ be the direct sums $L = \bigoplus_i L^{(i)}$ and $R = \bigoplus_i R^{(i)}$, as defined in Lemma~\ref{lem:cl-func-prod}. Then the conditionally linear distribution $\mu_{L,R}$ is the product distribution $\prod_{i=1}^m \mu_{L^{(i)},\,R^{(i)}}$ over $V \times V$.
480	\end{lemma}
481	\begin{proof}
482		A uniformly random $x \in V$ has independent components $x^{(i)}$, each uniformly distributed in $V^{(i)}$. Hence the pair $(L(x), R(x)) = \bigl( (L^{(i)}(x^{(i)}))_{i=1}^m,\, (R^{(i)}(x^{(i)}))_{i=1}^m \bigr)$ is distributed exactly as the product of the distributions $\mu_{L^{(i)},\,R^{(i)}}$ for $i = 1, 2, \dots, m$.
483	\end{proof}
