349	The Schwartz--Zippel lemma implies that low-degree polynomials form an
350	error-correcting code with good distance, the \emph{low-degree code} (a special
351	case of the generalized Reed--Muller code).
352	
353	\begin{definition}[Low-degree encoding]\label{def:low-degree-encoding}
354		\uses{def:polynomials-degree}
355		Fix an integer $m \in \N$ and let $M = 2^m$. For every $y \in \{0,1\}^m$

190			\E_{x \sim \mu} \sum_a \lVert (M^x_a - N^x_a)\, \ket{\psi} \rVert^2 \le O(\delta)\,,
191		\]
192		and we write $M^x_a \approx_\delta N^x_a$ to denote this when the state $\ket{\psi}$ and the distribution $\mu$ are clear from context. This distance is referred to as the \emph{state-dependent} distance.
193	\end{definition}
194	
195	\begin{definition}[Distance between strategies]\label{def:strategy-distance}
196		\uses{def:tensor-product-strategy, def:state-distance, def:povm-distance}
197		Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a nonlocal game and let $\mathcal S = (\psi, A, B)$ and $\mathcal S' = (\psi', A', B')$ be strategies for $\mathfrak G$. For $\delta \in [0,1]$ we say that \emph{$\mathcal S$ is $\delta$-close to $\mathcal S'$} if the following conditions hold.
198		\begin{enumerate}
199			\item The states $\ket{\psi}, \ket{\psi'}$ are states in the same Hilbert space $\mathcal H_A \ot \mathcal H_B$ and are $\delta$-close.
200			\item For all $x \in \mathcal X$ and $y \in \mathcal Y$, we have $A^x_a \approx_\delta (A')^x_a$ and $B^y_b \approx_\delta (B')^y_b$, with the approximations holding under the distribution $\mu$ (i.e.\ under its corresponding marginals), on either $\ket{\psi}$ or $\ket{\psi'}$.
201		\end{enumerate}
202	\end{definition}
203	
204	\begin{remark}[Asymptotic reading of the distance relations]\label{rem:asymptotic-distance}
205		Definitions~\ref{def:state-distance}, \ref{def:consistency}, and \ref{def:povm-distance} are asymptotic: every $\approx_\delta$ and $\simeq_\delta$ statement refers to families of states and measurement families indexed by an implicit parameter $n \in \N$, and the $O(\cdot)$ is taken as $n \to \infty$. None of these relations is a pointwise inequality with an explicit constant. By contrast, the corresponding relations used in the low individual degree chapters (Definitions~\ref{def:simeq} and~\ref{def:approx_delta}) carry no hidden constant. A formalization of the present chapter must therefore fix concrete-constant versions of the relations and re-verify the constant in each conversion fact below; for instance, the triangle inequality of Lemma~\ref{fact:triangle} hides a factor $2$ in the $O(\cdot)$.
206	\end{remark}
207	
208	We record several useful facts about the consistency measure and the state-dependent distance. For the statements imported without proof, readers are referred to Sections~4.4 and~4.5 of \cite{Natarajan2018NEEXP}.
209	
210	\begin{lemma}[Consistency versus closeness; Facts 4.13 and 4.14 in \cite{Natarajan2018NEEXP}]\label{fact:agreement}
211		\uses{def:consistency, def:povm-distance}
212		For POVMs $\{A^x_a\}$ and $\{B^x_a\}$, the following hold.
213		\begin{enumerate}
214			\item If $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$, then $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$.
215			\item If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ \emph{and} $\{A^x_a\}$ and $\{B^x_a\}$ are projective measurements, then $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$.
216			\item If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ and either $\{A^x_a\}$ or $\{B^x_a\}$ is a projective measurement, then $A^x_a \ot \Id_B \simeq_{\delta^{1/2}} \Id_A \ot B^x_a$.
217		\end{enumerate}
218	\end{lemma}
219	\begin{proof}
220		Stated in the source without proof; these are Facts 4.13 and 4.14 of \cite{Natarajan2018NEEXP}. For the first item, expand each term $\lVert (A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi} \rVert^2$ and use $ (A^x_a)^2 \le A^x_a$, $(B^x_a)^2 \le B^x_a$ together with completeness of the two POVMs: summing over $a$ and averaging over $x$ leaves exactly twice the off-diagonal mass, which is $O(\delta)$ by hypothesis. For the converse items, write the off-diagonal mass $\sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi}$ as an inner product involving $(A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi}$ and use projectivity of both families, or of one family combined with the Cauchy--Schwarz inequality; the latter route costs a square root in the error.
255		\]
256	\end{lemma}
257	\begin{proof}
258		By projectivity, $\sum_{a \in S} (A^x_a - A^x_a B^x_a) = \sum_{a \in S} A^x_a (A^x_a - B^x_a)$. Expanding the squared norm of the corresponding vector, the cross terms for distinct $a \ne a' \in S$ vanish because $A^x_a A^x_{a'} = 0$, so
259		\begin{align*}
260			\E_x \Bigl\lVert \sum_{a \in S} \bigl(A^x_a - A^x_a B^x_a\bigr) \ket{\psi} \Bigr\rVert^2
261			&= \E_x \sum_{a \in S} \bra{\psi} (A^x_a - B^x_a)^\dagger A^x_a (A^x_a - B^x_a) \ket{\psi}\\
262			&\le \E_x \sum_a \lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2\,,
263		\end{align*}
264		where the last step uses $A^x_a \le \Id$. All expectations are taken according to $\mu$, and the last quantity is at most $\delta$ by assumption.
265	\end{proof}
266	
267	\begin{lemma}[Triangle inequality; Fact 4.28 in \cite{Natarajan2018NEEXP}]\label{fact:triangle}
268		\uses{def:povm-distance}
269		If $A^x_a \approx_\delta B^x_a$ and $B^x_a \approx_{\eps} C^x_a$, then $A^x_a \approx_{\delta+\eps} C^x_a$.
270	\end{lemma}
271	\begin{proof}
272		Stated in the source without proof; it is Fact 4.28 of \cite{Natarajan2018NEEXP}. For every $x$ and $a$, $\lVert (A^x_a - C^x_a)\ket{\psi} \rVert^2 \le 2\lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2 + 2\lVert (B^x_a - C^x_a)\ket{\psi} \rVert^2$. Averaging over $x$ and summing over $a$ gives the claim; the factor $2$ is absorbed by the $O(\cdot)$ in Definition~\ref{def:povm-distance}.
273	\end{proof}
274	
275	\begin{lemma}[Triangle inequality for ``$\simeq$''; Proposition 4.29 in \cite{Ji2020LowIndividualDegree}]\label{fact:triangle-for-simeq}
276		\uses{def:consistency}
277		If $A^x_a \ot \Id_B \simeq_{\eps} \Id_A \ot B^x_a$, and $C^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$, and $C^x_a \ot \Id_B \simeq_\gamma \Id_A \ot D^x_a$, then
278		\[
279			A^x_a \ot \Id_B \simeq_{\eps + 2\sqrt{\delta+\gamma}} \Id_A \ot D^x_a\,.
280		\]
281	\end{lemma}
282	\begin{proof}
283		\uses{fact:agreement}
284		Stated in the source without proof; it is Proposition 4.29 of \cite{Ji2020LowIndividualDegree}. The two hypotheses involving $C$ convert, via Lemma~\ref{fact:agreement}, into state-dependent closeness of $C^x_a \ot \Id_B$ to both $\Id_A \ot B^x_a$ and $\Id_A \ot D^x_a$, hence of $\Id_A \ot B^x_a$ to $\Id_A \ot D^x_a$ at cost $O(\delta+\gamma)$. The first consistency then transfers from $B$ to $D$ by expanding the off-diagonal mass and applying the Cauchy--Schwarz inequality, which turns the squared-distance bound into the term $2\sqrt{\delta+\gamma}$.
285	\end{proof}
435			\item[(ii)] for each $k \in \{1, 2, \dots, \ell\}$ and $u \in L_{<k}(V)$, a register subspace $V_{k,\,u}$ of $V$, called the \emph{$k$-th factor space with prefix $u$};
436			\item[(iii)] for each $k \in \{1, 2, \dots, \ell\}$ and $u \in L_{<k}(V)$, a linear map $L_{k,\,u} \colon V_{k,\,u} \to V_{k,\,u}$, called the \emph{$k$-th linear map of $L$ with prefix $u$};
437		\end{enumerate}
438		such that the following conditions hold for all $k \in \{1, 2, \dots, \ell\}$:
439		\begin{enumerate}
440			\item $L_{\le k}$ is a $k$-level CL function on $V$;
441			\item $V = \bigoplus_{i=1}^{\ell} V_{i,\,x^{L_{<i}}}$ for all $x \in V$;
442			\item $L_{\le k}(x) = \sum_{i=1}^{k} x^{L_i}$ for all $x \in V$, where $L_i$ is shorthand notation for $L_{i,\,x^{L_{<i}}}$;
443			\item $L = L_{\le \ell}$.
444		\end{enumerate}
445		As in condition 3, we sometimes use $V_k$ and $L_k$ to denote $V_{k,\,u}$ and $L_{k,\,u}$ respectively, leaving the prefix $u$ implicit.
446	\end{lemma}
447	\begin{proof}
448		For the ``if'' direction, conditions 1 and 4 immediately exhibit $L$ as an $\ell$-level CL function. For the ``only if'' direction one constructs the marginals, factor spaces, and linear maps by induction on $\ell$. In the base case $\ell = 1$ take $L_{\le 1} = L$, $V_1 = V$, and $L_1 = L$. For the inductive step, write $L(x) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{V_{>1}})$ as in Definition~\ref{def:cl-func} and apply the inductive hypothesis to each $(\ell-1)$-level function $L_{>1,\,v}$, obtaining its marginals, factor spaces, and linear maps over $V_{>1}$. Define $L_{\le 1} = L_1$ with first factor space $V_1$, and for $k \ge 2$ define $L_{\le k}(x) = x^{L_1} + L'_{x^{L_1},\,<k}(x^{V_{>1}})$, with the $k$-th factor space and linear map of $L$ with prefix $u$ given by those of $L_{>1,\,v}$ at index $k-1$ with prefix $w$, where $v = u^{V_1}$ and $w = u^{V_{>1}}$. Conditions 1--4 are then verified directly from the inductive hypothesis: the direct-sum decomposition of $V_{>1}$ extends to $V$ by adjoining $V_1$, and the sum formula for $L_{\le k}$ follows by unfolding the inductive marginals.
449	\end{proof}
450	
451	The marginal functions, factor spaces, and linear maps of a given CL function $L$ need not be unique. For example, the identity function on $V = \F^n$ is a $1$-level CL function, but it can also be viewed as a $k$-level CL function for any $k \in \{2, \dots, n\}$ with an arbitrary partition of $V$ into factor spaces.
452	
453	\begin{lemma}[Concatenation of conditionally linear functions]\label{lem:cl-concat}
454		\uses{def:cl-func}
455		Let $\ell, k \ge 0$ be integers and let $U = \F^n$, $V = \F^m$ be linear spaces. Suppose $L$ is a $k$-level CL function on $U$ and, for each $u \in L(U)$, $R_u$ is an $\ell$-level CL function on $V$. Then the \emph{concatenation} $T$ of $L$ and $\{R_u\}_u$, defined by
456		\[
457			T(x) = L(x^U) + R_{L(x^U)}(x^V)\,,
458		\]
459		is a $(k+\ell)$-level conditionally linear function on $U \oplus V$.
460	\end{lemma}
461	\begin{proof}
462		By induction on $k$. The case $k = 0$ follows directly from Definition~\ref{def:cl-func}, since then $L = 0$ and $T$ acts by the single $\ell$-level function $R_0$ on the register subspace $V$. For the inductive step, write $L(x^U) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{U_{>1}})$ with complementary register subspaces $U_1$ and $U_{>1}$ of $U$. For each value $x^{L_1}$, the function $T_{>1,\,x^{L_1}}$ on $U_{>1} \oplus V$ sending $x^{U_{>1} \oplus V}$ to $L_{>1,\,x^{L_1}}(x^{U_{>1}}) + R_{x^{L_1} + x^{L_{>1}}}(x^V)$ is the concatenation of the $(k-1)$-level function $L_{>1,\,x^{L_1}}$ with a family drawn from $\{R_u\}$, hence is $(k+\ell-1)$-level by the induction hypothesis. The claim then follows from Definition~\ref{def:cl-func} applied with first subspace $U_1$ and first linear map $L_1$.
463	\end{proof}
464	
465	\begin{lemma}[Direct sums of conditionally linear functions]\label{lem:cl-func-prod}
466		\uses{def:cl-func, def:register-subspace}
467		Let $V^{(1)}, V^{(2)}, \dots, V^{(m)}$ be register subspaces of $V$ such that $V = \bigoplus_{j=1}^m V^{(j)}$. Suppose that, for each $j \in \{1, 2, \dots, m\}$, $L^{(j)}$ is an $\ell_j$-level conditionally linear function on $V^{(j)}$. Then the direct sum $L = \bigoplus_{j=1}^m L^{(j)}$, defined by
468		\[
469			L(x) = \sum_{j=1}^m L^{(j)}(x^{(j)})
470		\]
471		for all $x = \sum_{j=1}^m x^{(j)} \in \bigoplus_{j=1}^m V^{(j)}$, is an $\ell$-level CL function on $V$ for $\ell = \max_j \{\ell_j\}$.
472	\end{lemma}
473	\begin{proof}
474		Since an $\ell$-level CL function is also $k$-level conditionally linear for all $k \ge \ell$, it suffices to prove the claim when $\ell_j = \ell$ for all $j$. Proceed by induction on $\ell$. For $\ell = 1$ the functions $L^{(j)}$ are linear and the direct sum of linear maps is linear. For the inductive step, decompose each $L^{(j)}$ into its first-level linear part $L^{(j)}_1$ on $V^{(j)}_1$ and its family of $(\ell-1)$-level remainders $L^{(j)}_{>1,\,v_j}$ on $V^{(j)}_{>1}$. The direct sums of the first-level parts define a linear map on $V_1 = \bigoplus_j V^{(j)}_1$, and, for each prefix value $v = \sum_j v_j$, the direct sums of the remainders are $(\ell-1)$-level conditionally linear on $V_{>1} = \bigoplus_j V^{(j)}_{>1}$ by the induction hypothesis. This exhibits $L$ in the form required by Definition~\ref{def:cl-func}.
475	\end{proof}
476	
477	\begin{lemma}[Direct sums give product distributions]\label{lem:cl-dist-prod}
478		\uses{def:cl-dist, lem:cl-func-prod}
479		For each $i \in \{1, \dots, m\}$ let $L^{(i)}, R^{(i)} \colon V^{(i)} \to V^{(i)}$ be $\ell_i$-level conditionally linear functions, and let $L, R \colon V \to V$ be the direct sums $L = \bigoplus_i L^{(i)}$ and $R = \bigoplus_i R^{(i)}$, as defined in Lemma~\ref{lem:cl-func-prod}. Then the conditionally linear distribution $\mu_{L,R}$ is the product distribution $\prod_{i=1}^m \mu_{L^{(i)},\,R^{(i)}}$ over $V \times V$.
480	\end{lemma}
481	\begin{proof}
482		A uniformly random $x \in V$ has independent components $x^{(i)}$, each uniformly distributed in $V^{(i)}$. Hence the pair $(L(x), R(x)) = \bigl( (L^{(i)}(x^{(i)}))_{i=1}^m,\, (R^{(i)}(x^{(i)}))_{i=1}^m \bigr)$ is distributed exactly as the product of the distributions $\mu_{L^{(i)},\,R^{(i)}}$ for $i = 1, 2, \dots, m$.
483	\end{proof}
