545	\begin{lemma}[Product and twisted commutation relations]\label{lem:twisted-commutation}
546		\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
547		Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
548		\begin{enumerate}
549			\item For all $a, a' \in \F_q$ and $b \in \F_p$,
550			      \begin{equation}\label{eq:pauli-product-power}
551				      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
552				      \qquad \text{and} \qquad
553				      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
554			      \end{equation}
555			      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$, so each
556			      $\tau^W(a)$ is a unitary with eigenvalues that are $p$-th roots
557			      of unity.
558			\item For all $a, b \in \F_q^n$,
559			      % Paper equation label kept on the display it names.
560			      \begin{equation}\label{eq:twisted-fq}
561				      \tau^X(a)\, \tau^Z(b)
562				      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
563			      \end{equation}
564			      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
565			      $q = p$, $n = 1$ reads
566			      \begin{equation}\label{eq:twisted-fp}
567				      \sigma^X(a)\, \sigma^Z(b)
568				      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
569				      \qquad \text{for all } a, b \in \F_p\;.
570			      \end{equation}
571		\end{enumerate}
572	\end{lemma}
573	\begin{proof}
574		\uses{def:generalized-pauli, def:subfield-trace}
575		All identities are verified on computational basis states. For the product
576		relations with $W = X$, shifting twice by $a'$ and $a$ equals shifting by
577		$a + a'$; with $W = Z$, the phases $\omega^{\tr(aj)}\omega^{\tr(a'j)}$
578		combine by $\F_q$-linearity of the trace, and the power relation follows by
579		iterating. For the scalar twisted commutation,
580		$\tau^X(a)\tau^Z(b)\ket{j} = \omega^{\tr(bj)}\ket{j + a}$, while
581		$\tau^Z(b)\tau^X(a)\ket{j} = \omega^{\tr(b(j+a))}\ket{j + a} =
582		\omega^{\tr(ab)}\,\omega^{\tr(bj)}\ket{j + a}$. The multi-qudit relation
583		follows by applying the scalar relation factor by factor and summing the
584		exponents, using $\tr(a \cdot b) = \sum_i \tr(a_i b_i)$. For $q = p$ the
585		trace is the identity map, which gives \eqref{eq:twisted-fp}.

