 97	\begin{definition}[Low-degree polynomial measurements]\label{def:ld-meas}
 98		\uses{def:polyfunc, def:polymeasurements}
 99		Let $\polymeas{m}{q}{d}$ denote the set of POVM measurements whose outcomes correspond to polynomials $g\colon \F_q^m \to \F_q$ of individual degree at most $d$, that is, measurements indexed by $\polyfunc{m}{q}{d}$; this is the notion of Definition~\ref{def:polymeasurements}, and the argument order $(m,q,d)$ follows that definition (the paper orders the arguments as $(m,d,q)$). More generally, for an integer $k$ and tuples $m = (m_1,\ldots,m_k)$, $q = (q_1,\ldots,q_k)$, $d = (d_1,\ldots,d_k)$, let $\mathrm{PolyMeas}(m,q,d,k)$ denote the set of measurements $G = \{G_{g_1,\ldots,g_k}\}$ such that for each $i \in \{1,\ldots,k\}$, the outcome index $g_i$ is a polynomial $g_i\colon \F_{q_i}^{m_i} \to \F_{q_i}$ of individual degree at most $d_i$.
100	\end{definition}
